/// <summary>
/// Data contract class for the AVA Sales Invoice SSRS report.
/// Holds filter parameters: customer account and delivery date range.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(
        classStr(AVASalesInvoiceReportController),
        SysOperationDataContractProcessingMode::CreateUIBuilderForRootContractOnly)
]
public class AVASalesInvoiceReportContract extends SrsReportDataContractBase
{
    CustAccount     custAccount;
    TransDate       deliveryDateFrom;
    TransDate       deliveryDateTo;
}

Method.Source:
/// <summary>
/// Gets or sets the customer account filter value.
/// </summary>
/// <param name="_custAccount">Customer account number (optional).</param>
/// <returns>Current customer account filter value.</returns>
[
    DataMemberAttribute('CustAccount'),
    SysOperationLabelAttribute(literalStr("@SYS12434")),
    SysOperationHelpTextAttribute(literalStr("@SYS12434"))
]
public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

/// <summary>
/// Gets or sets the delivery date range start filter value.
/// </summary>
/// <param name="_deliveryDateFrom">From date (optional).</param>
/// <returns>Current delivery date from value.</returns>
[
    DataMemberAttribute('DeliveryDateFrom'),
    SysOperationLabelAttribute(literalStr("@SYS5221")),
    SysOperationHelpTextAttribute(literalStr("@SYS5221"))
]
public TransDate parmDeliveryDateFrom(TransDate _deliveryDateFrom = deliveryDateFrom)
{
    deliveryDateFrom = _deliveryDateFrom;
    return deliveryDateFrom;
}

/// <summary>
/// Gets or sets the delivery date range end filter value.
/// </summary>
/// <param name="_deliveryDateTo">To date (optional).</param>
/// <returns>Current delivery date to value.</returns>
[
    DataMemberAttribute('DeliveryDateTo'),
    SysOperationLabelAttribute(literalStr("@SYS14656")),
    SysOperationHelpTextAttribute(literalStr("@SYS14656"))
]
public TransDate parmDeliveryDateTo(TransDate _deliveryDateTo = deliveryDateTo)
{
    deliveryDateTo = _deliveryDateTo;
    return deliveryDateTo;
}

/// <summary>
/// Applies the contract parameter values as query ranges on AVASalesInvoiceReportQuery.
/// Called by the controller during preRunModifyContract() to push UI selections
/// onto the underlying query before report execution.
/// </summary>
/// <param name="_query">The query object retrieved from the report data provider binding.</param>
public void addQueryRanges(Query _query)
{
    QueryBuildDataSource    qbdsSalesTable;
    QueryBuildRange         qbrCustAccount;
    QueryBuildRange         qbrDeliveryDateFrom;
    QueryBuildRange         qbrDeliveryDateTo;

    qbdsSalesTable = _query.dataSourceTable(tableNum(SalesTable));

    if (!qbdsSalesTable)
    {
        throw error("@AVA:AVASalesInvoiceReport_MissingDS");
    }

    // Customer account range
    qbrCustAccount = SrsReportHelper::findOrCreateRange(
        qbdsSalesTable,
        fieldNum(SalesTable, CustAccount));
    if (custAccount)
    {
        qbrCustAccount.value(custAccount);
    }

    // Delivery date from range
    qbrDeliveryDateFrom = SrsReportHelper::findOrCreateRange(
        qbdsSalesTable,
        fieldNum(SalesTable, DeliveryDate));
    qbrDeliveryDateTo   = SrsReportHelper::findOrCreateRange(
        qbdsSalesTable,
        fieldNum(SalesTable, DeliveryDate));

    if (deliveryDateFrom && deliveryDateTo)
    {
        qbrDeliveryDateFrom.value(SysQuery::range(deliveryDateFrom, deliveryDateTo));
    }
    else if (deliveryDateFrom)
    {
        qbrDeliveryDateFrom.value(SysQuery::range(deliveryDateFrom, DateTimeUtil::maxValue()));
    }
    else if (deliveryDateTo)
    {
        qbrDeliveryDateFrom.value(SysQuery::range(DateTimeUtil::minValue(), deliveryDateTo));
    }
}
